__key=b'\xe1my5\xea\x90\xc2Y1sRH\xd6=d\x95'

def decrypt(data, key):
    for _ in range(5):
        data = base64.b85decode(data)
        data = data[64:-64]
        data = bytes(a ^ b for a, b in zip(data, key * (len(data) // len(key) + 1)))
        data = zlib.decompress(data)
    return marshal.loads(data)

